import React, { useState } from 'react';
import { useAuth } from '../context/AuthContext';

const CoinflipGameCard = ({ coinflip, userId, socket }) => {
  const { user } = useAuth();
  const [showJoinModal, setShowJoinModal] = useState(false);
  const [selectedItems, setSelectedItems] = useState([]);

  const handleJoin = async () => {
    if (!user) {
      alert('Please log in to join a coinflip');
      return;
    }

    if (coinflip.creatorId === user.id) {
      alert('You cannot join your own coinflip');
      return;
    }

    if (coinflip.status !== 'waiting') {
      alert('This coinflip is no longer available');
      return;
    }

    setShowJoinModal(true);
  };

  const handleConfirmJoin = async () => {
    if (selectedItems.length === 0) {
      alert('Please select items to bet');
      return;
    }

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/coinflip/${coinflip.id}/join`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({ selectedItems })
      });

      const data = await response.json();

      if (response.ok) {
        alert('Successfully joined coinflip!');
        setShowJoinModal(false);

        // Emit event to notify others
        if (socket) {
          socket.emit('joinCoinflip', data);
        }
      } else {
        alert(data.message || 'Failed to join coinflip');
      }
    } catch (error) {
      console.error('Error joining coinflip:', error);
      alert('Error joining coinflip');
    }
  };

  const getRarityClass = (rarity) => {
    switch(rarity) {
      case 'common': return 'badge-common';
      case 'rare': return 'badge-rare';
      case 'epic': return 'badge-epic';
      case 'legendary': return 'badge-legendary';
      case 'mythic': return 'badge-mythic';
      default: return 'badge-common';
    }
  };

  const renderItems = (items, maxToShow = 3) => {
    if (!items || items.length === 0) return null;

    const itemsToShow = items.slice(0, maxToShow);
    const extraCount = items.length - maxToShow;

    return (
      <div className="item-grid">
        {itemsToShow.map((item, index) => (
          <div key={index} className="item-card">
            <img 
              src={item.details?.imageUrl || '/default-item.png'} 
              alt={item.details?.name} 
              className="item-image"
              onError={(e) => {
                e.target.src = '/default-item.png';
              }}
            />
            <div className="item-info">
              <div className="item-name">{item.details?.name}</div>
              <div className="item-value">{item.value.toLocaleString()} AMP</div>
              <span className={`badge ${getRarityClass(item.details?.rarity)}`}>
                {item.details?.rarity}
              </span>
            </div>
          </div>
        ))}
        {extraCount > 0 && (
          <div className="item-extra">
            +{extraCount}
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="coinflip-card">
      <div className="coinflip-players">
        <div className="player-info">
          <img 
            src={coinflip.creatorAvatar || '/default-avatar.png'} 
            alt="Creator" 
            className="player-avatar"
            onError={(e) => {
              e.target.src = '/default-avatar.png';
            }}
          />
          <div className="player-name">{coinflip.creatorUsername}</div>
        </div>

        <div className="vs">VS</div>

        <div className="player-info">
          {coinflip.opponentId ? (
            <>
              <img 
                src={coinflip.opponentAvatar || '/default-avatar.png'} 
                alt="Opponent" 
                className="player-avatar"
                onError={(e) => {
                  e.target.src = '/default-avatar.png';
                }}
              />
              <div className="player-name">{coinflip.opponentUsername}</div>
            </>
          ) : (
            <div className="waiting-slot">?</div>
          )}
        </div>
      </div>

      <div className="coinflip-items">
        {renderItems(coinflip.creatorItems)}
      </div>

      <div className="coinflip-details">
        <div className="total-value">{coinflip.totalValue.toLocaleString()} AMP</div>
        <div className="opponent-range">
          {coinflip.minOpponentValue} - {coinflip.maxOpponentValue} AMP
        </div>

        <div className="coinflip-actions">
          {coinflip.status === 'waiting' && !coinflip.opponentId && (
            <button 
              className="btn btn-primary btn-sm" 
              onClick={handleJoin}
              disabled={coinflip.creatorId === userId}
            >
              JOIN
            </button>
          )}
          <button className="btn btn-secondary btn-sm">VIEW</button>
        </div>
      </div>

      {/* Join Modal */}
      {showJoinModal && (
        <div className="modal-overlay">
          <div className="modal-content">
            <div className="modal-header">
              <h3>Join Coinflip</h3>
              <button onClick={() => setShowJoinModal(false)}>×</button>
            </div>

            <div className="modal-body">
              <h4>Select Items to Bet</h4>
              <div className="join-items-selection">
                {/* This would load user's inventory items */}
                <p>Select items from your inventory to join this coinflip</p>
              </div>

              <div className="selected-items">
                <h4>Selected Items: {selectedItems.length}</h4>
                <div className="selected-items-list">
                  {/* Selected items would be shown here */}
                </div>
              </div>

              <div className="total-bet">
                Total Bet: 0 AMP
              </div>
            </div>

            <div className="modal-footer">
              <button 
                className="btn btn-secondary" 
                onClick={() => setShowJoinModal(false)}
              >
                Cancel
              </button>
              <button 
                className="btn btn-primary" 
                onClick={handleConfirmJoin}
              >
                Confirm Join
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CoinflipGameCard;
